// Glyphs are 5x7 bitmaps, with the most significant bit on the left.

export const GLYPH_WIDTH = 5;
export const GLYPH_HEIGHT = 7;

/** How the orbs move once the grid is laid out. */
export type DotMotion = "reveal" | "wave" | "scan" | "still";

export type DotGrid = {
	cols: number;
	rows: number;
	/** `cells[row][column]` is true when the orb is part of the mark. */
	cells: readonly (readonly boolean[])[];
};

// A missing glyph renders as a hollow box so an unsupported character is visible
// instead of silently collapsing the wordmark.
const MISSING_GLYPH: readonly number[] = [0x1f, 0x11, 0x11, 0x11, 0x11, 0x11, 0x1f];

const GLYPHS: Record<string, readonly number[]> = {
	A: [0x0e, 0x11, 0x11, 0x1f, 0x11, 0x11, 0x11],
	B: [0x1e, 0x11, 0x11, 0x1e, 0x11, 0x11, 0x1e],
	C: [0x0e, 0x11, 0x10, 0x10, 0x10, 0x11, 0x0e],
	D: [0x1e, 0x11, 0x11, 0x11, 0x11, 0x11, 0x1e],
	E: [0x1f, 0x10, 0x10, 0x1e, 0x10, 0x10, 0x1f],
	F: [0x1f, 0x10, 0x10, 0x1e, 0x10, 0x10, 0x10],
	G: [0x0e, 0x11, 0x10, 0x17, 0x11, 0x11, 0x0e],
	H: [0x11, 0x11, 0x11, 0x1f, 0x11, 0x11, 0x11],
	I: [0x0e, 0x04, 0x04, 0x04, 0x04, 0x04, 0x0e],
