const glyphRows = (character: string): readonly number[] => GLYPHS[character] ?? MISSING_GLYPH;

const bitAt = (row: number, column: number): boolean =>
	(row & (1 << (GLYPH_WIDTH - 1 - column))) !== 0;

/**
 * Lays text out as a dot grid. Lowercase letters are folded to uppercase, `\n`
 * starts a new line, and unsupported characters render as a hollow box.
 */
export function dotMatrixGrid(text: string, letterGap = 1, lineGap = 1): DotGrid {
	const lines = text.split("\n").map((line) => [...line.toUpperCase()].map(glyphRows));
	if (lines.every((glyphs) => glyphs.length === 0)) return { cols: 0, rows: 0, cells: [] };

	const cols = Math.max(
		...lines.map(
			(glyphs) => glyphs.length * GLYPH_WIDTH + Math.max(0, glyphs.length - 1) * letterGap
		)
	);
	const rows = lines.length * GLYPH_HEIGHT + (lines.length - 1) * lineGap;
	const cells = Array.from({ length: rows }, () => Array.from({ length: cols }, () => false));

	lines.forEach((glyphs, line) => {
		const top = line * (GLYPH_HEIGHT + lineGap);
		glyphs.forEach((glyph, index) => {
			const left = index * (GLYPH_WIDTH + letterGap);
			glyph.forEach((bits, y) => {
				const row = cells[top + y];
				if (row) for (let x = 0; x < GLYPH_WIDTH; x += 1) row[left + x] = bitAt(bits, x);
			});
		});
	});

	return { cols, rows, cells };
}

import type { Snippet } from "svelte";
import type { HTMLAttributes } from "svelte/elements";

export type DataAttributes = {
	[key: `data-${string}`]: string | null | undefined;
	[key: `aria-${string}`]: string | null | undefined;
};

export type PrimitiveAttributes = DataAttributes & {
	class?: string;
	id?: string;
	style?: string;
	role?: string;
	dir?: "ltr" | "rtl";
	tabindex?: number;
};

export type NativeProps<Element extends EventTarget = HTMLElement> = Omit<
	HTMLAttributes<Element>,
	"id"
> & {
	class?: string;
	id?: string;
	children?: Snippet;
};

export type Option =
	| string
	| {
			value?: string;
			label?: string;
			disabled?: boolean;
	  };

export type NormalizedOption = {
	value: string;
	label: string;
	disabled: boolean;
};

export function normalizeOption(option: Option): NormalizedOption {
	if (typeof option === "string") {
		return { value: option, label: option, disabled: false };
	}

	return {
		value: option.value ?? option.label ?? "",
		label: option.label ?? option.value ?? "",
		disabled: option.disabled ?? false,
	};
}

export function normalizeOptions(options: Option[]): NormalizedOption[] {
	return options.map(normalizeOption);
}

export function clampPercentage(value: number | null | undefined, min = 0, max = 100): number {
	if (value === null || value === undefined) return 100;
	if (!Number.isFinite(value) || !Number.isFinite(min) || !Number.isFinite(max) || max <= min) {
		return 0;
	}

	return Math.max(0, Math.min(100, ((value - min) / (max - min)) * 100));
}

import type { ClassValue } from "clsx";
import { clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]): string {
	return twMerge(clsx(inputs));
}
